import { spawn } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, existsSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

// #3817: run-hook.mjs imported its dist bundle by bare absolute path, which
// win32 rejects (ERR_UNSUPPORTED_ESM_URL_SCHEME), and the surrounding catch
// mapped the throw to {"continue":true} with exit 0, no stderr and no
// hook-timing row, so every hook no-oped on Windows through the dispatcher
// while its smoke test stayed green on exit codes. The fix imports through
// pathToFileURL and gives "bundle exists but cannot load" its own outcome.
//
// win32 is not available here, so the control is a synthetic unloadable
// bundle: a dist file with a syntax error throws on import on every platform.
// The runner is copied into a private tree so its `distDir` (../dist next to
// bin/) resolves to that bad bundle. Cases 1-3 fail on main (exit 0, empty
// stderr, no row); case 4 pins the legitimate absent-bundle case, which must
// stay silent on both.

const BIN_DIR = join(__dirname, '../../../bin');
const RUNNER_FILES = ['run-hook.mjs', 'output-guard.mjs', 'analytics-rotate.mjs', 'cc-output-keys.generated.mjs'];
const SECURITY_HOOK = 'pretool/bash/dangerous-command-blocker';
const PLAIN_HOOK = 'pretool/bash/sync-bash-dispatcher';

let root: string;
let home: string;
let runner: string;

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), 'bundle-error.'));
  home = join(root, 'home');
  mkdirSync(join(root, 'hooks', 'bin'), { recursive: true });
  mkdirSync(join(root, 'hooks', 'dist'), { recursive: true });
  mkdirSync(home, { recursive: true });
  for (const f of RUNNER_FILES) copyFileSync(join(BIN_DIR, f), join(root, 'hooks', 'bin', f));
  runner = join(root, 'hooks', 'bin', 'run-hook.mjs');
  // Present but unloadable: an unterminated export is a SyntaxError on import.
  writeFileSync(join(root, 'hooks', 'dist', 'pretool.mjs'), 'export const hooks = {\n', 'utf8');
});

afterEach(() => {
  rmSync(root, { recursive: true, force: true });
});

function payload(): string {
  return JSON.stringify({
    hook_event_name: 'PreToolUse',
    session_id: '00000000-0000-4000-8000-000000000000',
    cwd: '/tmp',
    tool_name: 'Bash',
    tool_input: { command: 'echo hi' },
  });
}

function run(hook: string, args: string[] = []): Promise<{ code: number | null; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    const child = spawn('node', [runner, hook, ...args], {
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, HOME: home, USERPROFILE: home, CLAUDE_PROJECT_DIR: root },
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (c) => { stdout += String(c); });
    child.stderr.on('data', (c) => { stderr += String(c); });
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.stdin.end(payload());
  });
}

function timingRows(): Array<Record<string, unknown>> {
  const file = join(home, '.claude', 'analytics', 'hook-timing.jsonl');
  if (!existsSync(file)) return [];
  return readFileSync(file, 'utf8').trim().split('\n').filter(Boolean).map((l) => JSON.parse(l));
}

const STDERR_RE = /\[orchestkit\] ERROR: hook "[^"]+" bundle at .*pretool\.mjs exists but failed to load \(SyntaxError: /;

describe('run-hook.mjs when the dist bundle exists but cannot be imported (#3817)', () => {
  it('exits 2, names the file on stderr and records verdict=bundle-error for a security hook', async () => {
    const r = await run(SECURITY_HOOK);
    expect(r.code).toBe(2);
    expect(r.stderr).toMatch(STDERR_RE);
    expect(r.stderr).toContain('#3817');
    expect(r.stdout.split('\n').some((l) => l.startsWith('{'))).toBe(false);
    const rows = timingRows();
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({ hook: SECURITY_HOOK, ok: false, verdict: 'bundle-error' });
    expect(typeof rows[0].t_bundle_ms).toBe('number');
  }, 20000);

  it('exits 1 with the same stderr line and row for a non-security hook', async () => {
    const r = await run(PLAIN_HOOK);
    expect(r.code).toBe(1);
    expect(r.stderr).toMatch(STDERR_RE);
    expect(timingRows()[0]).toMatchObject({ hook: PLAIN_HOOK, ok: false, verdict: 'bundle-error' });
  }, 20000);

  it('exits 2 for a non-security hook that passes --rewake', async () => {
    const r = await run(PLAIN_HOOK, ['--rewake']);
    expect(r.code).toBe(2);
    expect(r.stderr).toMatch(STDERR_RE);
  }, 20000);

  it('stays silent with exit 0 and no row when the bundle file is absent', async () => {
    rmSync(join(root, 'hooks', 'dist', 'pretool.mjs'));
    const r = await run(SECURITY_HOOK);
    expect(r.code).toBe(0);
    expect(r.stdout.trim()).toBe(JSON.stringify({ continue: true, suppressOutput: true }));
    expect(r.stderr).toBe('');
    expect(timingRows()).toHaveLength(0);
  }, 20000);
});
